css:
.rm-t-tech-dark{padding:0 0 46px;background:#f7f9fc;color:#243141;font-size:13px;line-height:1.66;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei","Noto Sans SC",sans-serif;}
.rm-t-tech-dark .rm-head{position:relative;margin:0;padding:36px 46px 30px;background:linear-gradient(135deg,#111827 0%,#0b1220 60%,#111d33 100%);color:#e8eef7;}
.rm-t-tech-dark .rm-head::after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:linear-gradient(90deg,#22d3ee 0%,#0ea5e9 46%,rgba(14,165,233,0) 100%);}
.rm-t-tech-dark .rm-name{margin:0;font-size:31px;line-height:1.2;font-weight:700;letter-spacing:.02em;color:#f8fafc;}
.rm-t-tech-dark .rm-name::after{content:"";display:inline-block;width:7px;height:7px;margin-left:12px;vertical-align:7px;border-radius:50%;background:#22d3ee;box-shadow:0 0 10px rgba(34,211,238,.8);}
.rm-t-tech-dark .rm-role{margin:8px 0 0;font-family:ui-monospace,"SFMono-Regular",Consolas,"Courier New",monospace;font-size:11.5px;letter-spacing:.14em;color:#67e8f9;}
.rm-t-tech-dark .rm-contact{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 30px;margin:18px 0 0;max-width:600px;}
.rm-t-tech-dark .rm-k{font-family:ui-monospace,"SFMono-Regular",Consolas,"Courier New",monospace;font-size:9px;letter-spacing:.18em;color:#8ba0bd;text-transform:uppercase;}
.rm-t-tech-dark .rm-v{font-size:12px;color:#dbe6f3;}
.rm-t-tech-dark .rm-photo{width:90px;height:90px;background:#0f1a2a;border:1px solid #1f3348;}
.rm-t-tech-dark .rm-body{padding:0 46px;}
.rm-t-tech-dark .rm-sec{margin-top:24px;}
.rm-t-tech-dark .rm-sec-h{display:flex;align-items:baseline;gap:8px;margin:0 0 11px;padding-bottom:5px;border-bottom:1px solid #dbe3ee;}
.rm-t-tech-dark .rm-sec-t{font-family:ui-monospace,"SFMono-Regular",Consolas,"Courier New",monospace;font-size:12px;font-weight:700;letter-spacing:.12em;color:#0b1220;}
.rm-t-tech-dark .rm-sec-t::before{content:"//";margin-right:7px;color:#0891b2;font-weight:700;letter-spacing:0;}
.rm-t-tech-dark .rm-summary{color:#3b4a5e;font-size:12.8px;line-height:1.74;}
.rm-t-tech-dark .rm-item{margin:0 0 11px;}
.rm-t-tech-dark .rm-item-t{font-weight:650;color:#0b1220;}
.rm-t-tech-dark .rm-item-role{margin-left:7px;font-size:12.2px;color:#5b6b80;}
.rm-t-tech-dark .rm-date{font-family:ui-monospace,"SFMono-Regular",Consolas,"Courier New",monospace;font-size:10.5px;color:#5f7288;}
.rm-t-tech-dark .rm-item-sub{margin-top:2px;font-size:11.5px;color:#63758c;}
.rm-t-tech-dark .rm-bullets{margin:5px 0 0;padding-left:15px;}
.rm-t-tech-dark .rm-bullets li{margin:3px 0;color:#31404f;}
.rm-t-tech-dark .rm-bullets li::marker{color:#0e9db8;}
.rm-t-tech-dark .rm-sec-campus .rm-item-t{color:#0b1220;}
.rm-t-tech-dark .rm-sec-hobbies .rm-tags{gap:6px;}
.rm-t-tech-dark .rm-edu-courses{margin-top:3px;font-size:11.5px;color:#5b6b80;}
.rm-t-tech-dark .rm-edu-courses .rm-k{margin-right:7px;color:#8ba0bd;}
.rm-t-tech-dark .rm-skill-row{grid-template-columns:104px minmax(0,1fr);gap:10px;margin:0 0 7px;}
.rm-t-tech-dark .rm-skill-k{font-family:ui-monospace,"SFMono-Regular",Consolas,"Courier New",monospace;font-size:11.5px;font-weight:600;color:#0f172a;}
.rm-t-tech-dark .rm-tags{gap:5px;}
.rm-t-tech-dark .rm-tag{padding:1px 8px;border:1px solid #164e63;border-radius:3px;background:#0f172a;color:#a5f3fc;font-size:11px;line-height:1.7;box-shadow:0 0 10px rgba(34,211,238,.16);}
.rm-t-tech-dark .rm-award-row{margin:0 0 7px;align-items:baseline;}
.rm-t-tech-dark .rm-award-t{font-weight:600;color:#0b1220;}
.rm-t-tech-dark .rm-award-desc{font-size:11.5px;color:#5b6b80;}
.rm-t-tech-dark strong{color:#0b1220;}
